'use client';

import React, { useState } from 'react';
import { Icons } from './Icons';

export type NavTab =
  | 'search'
  | 'pnr'
  | 'live'
  | 'trips'
  | 'payments'
  | 'refunds'
  | 'help'
  | 'microservices'
  | 'station'
  | 'reviews';

interface NavItem {
  id: NavTab;
  label: string;
  icon: keyof typeof Icons;
  badge?: number;
}

interface NavbarProps {
  activeTab: NavTab;
  setActiveTab: (tab: NavTab) => void;
  tripCount: number;
  isLoggedIn: boolean;
  user: { name: string; email: string; avatar: string } | null;
  onOpenAuth: () => void;
  onLogout: () => void;
  onOpenWallet: () => void;
  onOpenNotifications: () => void;
  onOpenAiAssistant: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  activeTab,
  setActiveTab,
  tripCount,
  isLoggedIn,
  user,
  onOpenAuth,
  onLogout,
  onOpenWallet,
  onOpenNotifications,
  onOpenAiAssistant,
}) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const NAV_ITEMS: NavItem[] = [
    { id: 'search', label: 'Search', icon: 'search' },
    { id: 'pnr', label: 'PNR', icon: 'ticket' },
    { id: 'live', label: 'Live', icon: 'live' },
    { id: 'trips', label: 'Trips', icon: 'user', badge: tripCount },
    { id: 'payments', label: 'Payments', icon: 'card' },
    { id: 'refunds', label: 'Refunds', icon: 'refresh' },
    { id: 'help', label: 'Help', icon: 'help' },
    { id: 'station', label: 'Stations', icon: 'building' },
    { id: 'reviews', label: 'Reviews', icon: 'star' },
    { id: 'microservices', label: 'Services', icon: 'activity' },
  ];

  const IconComponent = (name: keyof typeof Icons, className?: string) => {
    const SvgIcon = Icons[name];
    return SvgIcon ? <SvgIcon className={className} /> : null;
  };

  return (
    <header className="sticky top-0 z-40 border-b border-stone-200 bg-white/90 backdrop-blur-xl">
      <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6">
        {/* Brand Logo */}
        <button
          onClick={() => setActiveTab('search')}
          className="flex items-center gap-3 text-left focus:outline-none group shrink-0"
        >
          <div className="grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-orange-500 to-orange-600 text-white shadow-lg shadow-orange-500/20 transition-transform group-hover:scale-105">
            <Icons.train className="h-5 w-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="text-xl font-bold tracking-tight text-stone-900" style={{ fontFamily: 'Outfit, sans-serif' }}>RailGo</span>
              <span className="rounded-full bg-orange-50 px-2 py-0.5 text-[10px] font-bold text-orange-700 border border-orange-200">28</span>
            </div>
            <p className="text-[11px] font-medium text-stone-400">IRCTC Partner</p>
          </div>
        </button>

        {/* Desktop Navigation */}
        <nav className="hidden items-center gap-1 xl:flex">
          {NAV_ITEMS.map(({ id, label, icon, badge }) => {
            const isActive = activeTab === id;
            return (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                className={`flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-semibold whitespace-nowrap transition-all ${
                  isActive
                    ? 'bg-orange-50 text-orange-700 shadow-sm'
                    : 'text-stone-500 hover:bg-stone-100 hover:text-stone-900'
                }`}
              >
                <span className={isActive ? 'text-orange-600' : 'text-stone-400'}>
                  {IconComponent(icon, 'h-4 w-4')}
                </span>
                <span>{label}</span>
                {badge && badge > 0 ? (
                  <span className="grid h-5 min-w-5 place-items-center rounded-full bg-orange-600 text-[10px] font-bold text-white px-1.5">
                    {badge}
                  </span>
                ) : null}
              </button>
            );
          })}
        </nav>

        {/* Right Actions */}
        <div className="flex items-center gap-2 shrink-0">
          {/* AI Assistant Button */}
          <button
            onClick={onOpenAiAssistant}
            className="hidden lg:flex items-center gap-2 rounded-xl border border-indigo-200 bg-indigo-50 px-3 py-2 text-sm font-semibold text-indigo-700 hover:bg-indigo-100 transition-all"
          >
            <Icons.bot className="h-4 w-4 text-indigo-600" />
            <span>RailAI</span>
          </button>

          {/* Wallet Button */}
          <button
            onClick={onOpenWallet}
            className="flex items-center gap-2 rounded-xl border border-orange-200 bg-orange-50 px-3 py-2 text-sm font-semibold text-orange-700 hover:bg-orange-100 transition-all"
          >
            <Icons.wallet className="h-4 w-4 text-orange-600" />
            <span className="hidden sm:inline">₹2,500</span>
          </button>

          {/* Notifications */}
          <button
            onClick={onOpenNotifications}
            className="relative rounded-xl border border-stone-200 bg-white p-2.5 text-stone-500 hover:bg-stone-50 hover:text-stone-700 transition-all"
          >
            <Icons.bell className="h-4 w-4" />
            <span className="absolute top-2 right-2 h-2 w-2 rounded-full bg-orange-500 ring-2 ring-white" />
          </button>

          {/* User */}
          {isLoggedIn && user ? (
            <div className="hidden sm:flex items-center gap-2 pl-2 border-l border-stone-200">
              <div className="grid h-8 w-8 place-items-center rounded-lg bg-gradient-to-br from-orange-500 to-orange-600 font-bold text-xs text-white shadow-sm">
                {user.avatar}
              </div>
              <button
                onClick={onLogout}
                title="Log out"
                className="p-2 text-stone-400 hover:text-red-600 transition-colors"
              >
                <Icons.logout className="h-4 w-4" />
              </button>
            </div>
          ) : (
            <button
              onClick={onOpenAuth}
              className="btn-brand text-xs px-3.5 py-2 flex items-center gap-1.5"
            >
              <Icons.login className="h-3.5 w-3.5" />
              <span className="hidden sm:inline">Log in</span>
            </button>
          )}

          {/* Mobile Hamburger */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="xl:hidden p-2 text-stone-500 hover:text-stone-900 rounded-lg hover:bg-stone-100 transition-all"
          >
            {mobileMenuOpen ? <Icons.x className="h-6 w-6" /> : <Icons.menu className="h-6 w-6" />}
          </button>
        </div>
      </div>

      {/* Mobile Drawer */}
      {mobileMenuOpen && (
        <div className="xl:hidden border-t border-stone-200 bg-white/95 backdrop-blur-xl animate-fade-in">
          <nav className="px-4 py-3 space-y-1 max-h-[70vh] overflow-y-auto">
            {NAV_ITEMS.map(({ id, label, icon, badge }) => (
              <button
                key={id}
                onClick={() => {
                  setActiveTab(id);
                  setMobileMenuOpen(false);
                }}
                className={`flex items-center gap-3 w-full rounded-xl px-3 py-3 text-sm font-semibold transition-all ${
                  activeTab === id
                    ? 'bg-orange-50 text-orange-700'
                    : 'text-stone-600 hover:bg-stone-50'
                }`}
              >
                <span className={activeTab === id ? 'text-orange-600' : 'text-stone-400'}>
                  {IconComponent(icon, 'h-4 w-4')}
                </span>
                <span>{label}</span>
                {badge && badge > 0 && (
                  <span className="ml-auto grid h-5 min-w-5 place-items-center rounded-full bg-orange-600 text-[10px] font-bold text-white px-1.5">
                    {badge}
                  </span>
                )}
              </button>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
};
